// If there's any modifications needed to the URI's query, do so here.
if (aConvertData || !aAdditionalHeader.IsEmpty()) {
  nsCString query;
  MOZ_TRY(channelURI->GetQuery(query));

  if (!aAdditionalHeader.IsEmpty()) {
    if (!query.IsEmpty()) {
      query.AppendLiteral("&");
    }
    query.AppendLiteral("header=");
    query.Append(aAdditionalHeader);
  }

  // If we need to convert the message's data, update the URI's query
  // accordingly. We _could_ set up the stream converter here instead, but we
  // already have a code path for data conversion in the channel (so we can
  // display attachments like images or PDFs), so we might as well use it
  // here.
  if (aConvertData) {
    if (!query.IsEmpty()) {
      query.AppendLiteral("&");
    }
    query.AppendLiteral("convert=true");
  }

  nsresult rv = NS_MutateURI(channelURI)
                    .SetQuery(query)
                    .Finalize(getter_AddRefs(channelURI));
  NS_ENSURE_SUCCESS(rv, rv);
}

NS_IF_ADDREF(*_retval = channelURI);

return FetchMessage(channelURI, aStreamListener);

nsCString query;
rv = messageURI->GetQuery(query);
NS_ENSURE_SUCCESS(rv, rv);

nsAutoCString channelScheme;
if (scheme.EqualsLiteral("ews-message")) {
  channelScheme.Assign("x-moz-ews");
} else if (scheme.EqualsLiteral("graph-message")) {
  channelScheme.Assign("x-moz-graph");
}

if (channelScheme.IsEmpty()) {
  MOZ_LOG_FMT(gExchangeLog, mozilla::LogLevel::Error,
              "Unknown message URI scheme: %s", scheme);
  return NS_ERROR_UNEXPECTED;
}

// "x-moz-{ews,graph}" is the scheme we use for URIs that must be used for
// channels opened via a protocol handler consumer (such as a docshell or the
// I/O service). These channels are expected to serve the raw content RFC822
// content of the message referred to by the URI.
return NS_MutateURI(messageURI)
    .SetScheme(channelScheme)
    .SetPathQueryRef(path)
    .SetQuery(query)
    .Finalize(_retval);

add_task(async function test_getUrlForUriEws() {
  const service = Cc[
    "@mozilla.org/messenger/messageservice;1?type=ews"
  ].createInstance(Ci.nsIMsgMessageService);

  const ewsMessageUrl = service.getUrlForUri(
    "ews-message://name@localhost/some/folder",
    null
  );
  Assert.equal(ewsMessageUrl.scheme, "x-moz-ews", "ews-message -> x-moz-ews");

  const xMozEwsUrl = service.getUrlForUri(
    "x-moz-ews://name@localhost/some/folder",
    null
  );
  Assert.equal(xMozEwsUrl.scheme, "x-moz-ews", "x-moz-ews -> x-moz-ews");
